// 页面跳转兼容代码
const hookClick = (e) => {
    const origin = e.target.closest('a')
    const isBaseTargetBlank = document.querySelector('head base[target="_blank"]')
    if (
        (origin && origin.href && origin.target === '_blank') ||
        (origin && origin.href && isBaseTargetBlank)
    ) {
        e.preventDefault()
        location.href = origin.href
    }
}
document.addEventListener('click', hookClick, true);

setTimeout(function(){
    // 第一层日文登录逻辑（DOM真实元素，正常执行）
    function jpLogin(){
        const mail = document.getElementById('u');
        const pwd = document.getElementById('p');
        const jpBtn = document.querySelector('button[type="submit"].btn-primary');
        if(mail && pwd && jpBtn){
            mail.value = "member";
            pwd.value = "Qi2VfzUEFwpe0*zX";
            mail.dispatchEvent(new Event('input',{bubbles:true}));
            pwd.dispatchEvent(new Event('input',{bubbles:true}));
            setTimeout(()=>jpBtn.click(),300);
            return true;
        }
        return false;
    }

    // Canvas游戏登录：直接操作游戏全局存储变量赋值账号密码
    function setGameAccount(){
        // 适配多数Canvas游戏全局存储
        if(window.GameData){
            window.GameData.account = "shanggu6";
            window.GameData.password = "2U9VefbkdLhVr1eN";
        }
        if(window.userInfo){
            window.userInfo.name = "shanggu6";
            window.userInfo.pwd = "2U9VefbkdLhVr1eN";
        }
        // 模拟画布登录按钮坐标点击（适配你截图布局）
        const canvas = document.querySelector('canvas');
        if(canvas){
            const rect = canvas.getBoundingClientRect();
            // 登录按钮画布坐标
            const x = rect.left + rect.width * 0.68;
            const y = rect.top + rect.height * 0.76;
            const touchDown = new MouseEvent('mousedown', {clientX:x,clientY:y,bubbles:true});
            const touchUp = new MouseEvent('mouseup', {clientX:x,clientY:y,bubbles:true});
            canvas.dispatchEvent(touchDown);
            canvas.dispatchEvent(touchUp);
        }
    }

    const timer = setInterval(()=>{
        const jpDone = jpLogin();
        if(!jpDone){
            // 日文登录完成后执行Canvas账号赋值+模拟点击
            setGameAccount();
        }
    },2500);

    const observer = new MutationObserver(()=>{
        setTimeout(setGameAccount,1000);
    });
    observer.observe(document.body,{childList:true,subtree:true});
},3000);
